def solution(input_str):
    """
    Solve the lucky region problem.

    A region is lucky if the number of islands in it contains only digits 4 and 7.
    We can merge regions by building roads. Each merge costs 1 road and combines two regions.

    Returns minimum number of roads needed to create at least one lucky region.
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1\n'

    try:
        n, m = map(int, lines[0].split())
    except (ValueError, IndexError):
        return '-1\n'

    # Handle trivial case m=0 (no edges)
    if m == 0:
        if n in [4, 7] or str(n).replace('4', '').replace('7', '') == '':
            return '0\n'
        return '-1\n'

    # Union-Find for connected components
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            if size[px] < size[py]:
                px, py = py, px
            parent[py] = px
            size[px] += size[py]

    # Process all edges
    for i in range(1, min(m + 1, len(lines))):
        line = lines[i].strip()
        if not line:
            continue
        try:
            u, v = map(int, line.split())
            union(u, v)
        except (ValueError, IndexError):
            continue

    # Collect component sizes
    component_sizes = set()
    for i in range(1, n + 1):
        root = find(i)
        component_sizes.add(size[root])

    component_sizes = sorted(list(component_sizes), reverse=True)

    # Check if any component is already lucky
    def is_lucky(x):
        return all(c in '47' for c in str(x))

    if any(is_lucky(s) for s in component_sizes):
        return '0\n'

    # Generate lucky numbers up to n
    lucky_numbers = []

    def generate_lucky(current_val):
        for d in [4, 7]:
            new_val = current_val * 10 + d
            if new_val <= n:
                lucky_numbers.append(new_val)
            else:
                break
            # Try both 4 and 7 at next power of 10 only if we haven't exceeded
            if new_val <= n:
                for dd in [4, 7]:
                    next_val = new_val * 10 + dd
                    if next_val <= n:
                        lucky_numbers.append(next_val)
                    else:
                        break

    # Generate all powers and their 4/7 combinations
    q = [4, 7]
    while q:
        curr = q.pop(0)
        if curr > n:
            continue
        lucky_numbers.append(curr)
        q.append(curr * 10 + 4)
        q.append(curr * 10 + 7)

    lucky_numbers = sorted(lucky_numbers)

    # DP to find minimum components for each reachable sum
    # dp[j] = minimum number of components needed to get a component of total size j
    total_max = sum(component_sizes) if component_sizes else n
    total_max = min(total_max, n)

    dp = {}
    dp[0] = 0

    for s in component_sizes:
        # Iterate in reverse to avoid using same component multiple times for one sum
        # We process existing keys to ensure correctness
        keys_list = sorted(dp.keys())
        for j in range(total_max, s - 1, -1):
            if (j - s) in dp and dp[j - s] != float('inf'):
                new_val = dp[j - s] + 1
                if j not in dp or new_val < dp[j]:
                    dp[j] = new_val

    # Find minimum roads for any achievable lucky number
    min_roads = float('inf')
    found_valid = False

    for target in lucky_numbers:
        if target in dp and dp[target] != float('inf'):
            # dp[target] is the count of components needed
            # roads needed = components - 1 (since we start with all separate)
            min_roads = min(min_roads, dp[target] - 1)
            found_valid = True

    if found_valid:
        return f"{min_roads}\n"
    else:
