    # This function determines who wins with optimal play
    # Uses Sprague-Grundy theorem

    @lru_cache(maxsize=None)
    def grundy(state):
        r = len(state)
        if r == 0 or state == tuple(tuple('.' for _ in range(len(state[0]))) for _ in range(r)):
            return 0

        reachable = set()

        for r_idx in range(r):
            for c_idx in range(len(state[r_idx])):
                if state[r_idx][c_idx] == 'O':
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        seq = [(r_idx, c_idx)]
                        while True:
                            nr, nc = seq[-1]
                            n = r_idx
                            m = c_idx
                            while True:
                                if 0 <= n + dr < r and 0 <= m + dc < len(state[n + dr]):
                                    if state[n + dr][m + dc] == 'O':
                                        seq.append((n + dr, m + dc))
                                        n += dr
                                        m += dc
                                    else:
                                        break
                                else:
                                    break

                    if len(seq) == 0:
                        continue

                    for mask in range(1, 1 << len(seq)):
                        new_board = [list(row) for row in state]
                        for idx in range(len(seq)):
                            rr, rc = seq[idx]
                            if (mask >> idx) & 1:
                                new_board[rr][rc] = '.'
                        reachable.add(grundy(tuple(tuple(cell for cell in row) for row in new_board)))

        g = 0
        while g in reachable:
            g += 1
        return g

    result = grundy(board)

    return "Karlsson\n" if result != 0 else "Lillebor\n"


