import math
import bisect

def solution(input_str: str) -> str:
    # Parse input
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Calculate all volumes (π * r^2 * h)
    volumes = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        r, h = int(parts[0]), int(parts[1])
        volumes.append(math.pi * r * r * h)

    # Coordinate compression on volume values
    unique = sorted(set(volumes))
    m = len(unique)

    # Segment tree for max prefix query (1-indexed, internal 0-indexed)
    size = 1
    while size < m:
        size *= 2

    tree = [0.0] * (2 * size)

    def update(pos, val):
        """Update position pos (0-indexed) with value val"""
        idx = pos + size
        while idx > 0:
            tree[idx] = max(tree[idx], val)
            idx //= 2

    def query(l, r):
        """Query max in range [l, r] inclusive (0-indexed)"""
        res = 0.0
        l += size
        r += size
        while l <= r:
            if l % 2 == 1:
                res = max(res, tree[l])
                l += 1
            if r % 2 == 0:
                res = max(res, tree[r])
                r -= 1
            l //= 2
            r //= 2
        return res

    max_ans = 0.0

    for v in volumes:
        # Find position of v in unique volumes
        pos = bisect.bisect_left(unique, v)

        # Query max for all volumes strictly less than current v
        # These are at positions [0, pos-1] in the unique array
        if pos > 0:
            prev_max = query(0, pos - 1)
            curr = prev_max + v
        else:
            curr = v

        # Update at position 'pos' with current sum
        update(pos, curr)

        # Track global maximum
        if curr > max_ans:
            max_ans = curr

    return f"{max_ans:.3f}"

