    F, B, N = map(int, lines[0].split())
    petals = list(map(int, lines[1].split()))
    chocolates = list(map(int, lines[2].split()))

    # Polynomial multiplication
    def poly_mul(A, B):
        n, m = len(A), len(B)
        result = [0] * (n + m - 1)
        for i in range(n):
            if A[i] == 0:
                continue
            for j in range(m):
                result[i + j] = (result[i + j] + A[i] * B[j]) % MOD
        return result

    # Polynomial power using binary exponentiation
    def poly_pow(base, n):
        if n == 0:
            return [1]
        result = [1]
        while n > 0:
            if n & 1:
                result = poly_mul(result, base)
            base = poly_mul(base, base)
            n >>= 1
        return result

    # Build base flower polynomial
    if not petals:
        base = [1]
    else:
        max_degree = max(petals)
        base = [0] * (max_degree + 1)
        for p in petals:
            base[p] = 1

    # Compute flower distribution (N-th power of base polynomial)
    flower_poly = poly_pow(base, N)

    # Compute chocolate distribution using DP
    # Maximum meaningful sum to check
    max_choc = N * max(chocolates) if chocolates else 0
    dp = [0] * (max_choc + 1)
    dp[0] = 1

    for c in chocolates:
        for s in range(max_choc, c - 1, -1):
            dp[s] = (dp[s] + dp[s - c]) % MOD

    # Compute answer: sum of (flower_ways[s] * chocolate_ways[s]) for all s
    ans = 0
    for i in range(min(len(flower_poly), max_choc + 1)):
        ans = (ans + flower_poly[i] * dp[i]) % MOD

    return f"{ans}"

