def solution(input_str):
    """
    Solves the problem of orienting edges in a connected undirected graph
    to make it strongly connected, if possible.
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    edges = []

    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)
        edges.append((u, v))

    # Find bridges using Tarjan's algorithm
    tin = [0] * (n + 1)
    low = [0] * (n + 1)
    timer = [0]
    bridges = set()

    def dfs_bridges(u, p=-1):
        timer[0] += 1
        tin[u] = low[u] = timer[0]
        for v in adj[u]:
            if v == p:
                continue
            if tin[v]:
                low[u] = min(low[u], tin[v])
            else:
                dfs_bridges(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > tin[u]:
                    bridges.add((min(u, v), max(u, v)))

    dfs_bridges(1)

    if bridges:
        return "0\n"

    # For a 2-edge-connected graph (no bridges), 
    # perform DFS to construct a strong orientation
    # tree edges: parent -> child (for reachability from root)
    # back edges: descendant -> ancestor (using DFS discovery times)

    orient = {}

    def dfs_orient(u, p=-1):
        for v in adj[u]:
            if v == p:
                continue
            # Tree edge
            orient[(u, v)] = 1
            dfs_orient(v, u)
            # Back edge (non-tree)
            if (v, u) not in orient:
                orient[(u, v)] = 2

    dfs_orient(1)

    result = []
    for u, v in edges:
        if orient.get((u, v)) == 1:
            result.append((u, v))
        elif orient.get((v, u)) == 1:
            result.append((v, u))
        elif orient.get((u, v)):
            result.append((u, v))
        else:
            result.append((v, u))

    return '\n'.join(f"{u} {v}" for u, v in result) + '\n'


