import sys
from itertools import combinations_with_replacement

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, r = map(int, lines[0].split())

    def dist_sq(p):
        return p[0]**2 + p[1]**2

    def evaluate(config):
        """Calculate sum of pairwise squared distances"""
        total = 0
        m = len(config)
        for i in range(m):
            for j in range(i+1, m):
                dx = config[i][0] - config[j][0]
                dy = config[i][1] - config[j][1]
                total += dx*dx + dy*dy
        return total

    # Generate all valid integer points in/on the circle
    valid_pts = []
    r2 = r * r
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if dist_sq((x, y)) <= r2:
                valid_pts.append((x, y))

    # Sort by distance from origin (descending)
    valid_pts.sort(key=dist_sq, reverse=True)

    # Find points at maximum boundary
    max_pts = [p for p in valid_pts if dist_sq(p) == r2]

    # Use fewer candidates to limit search space
    candidates = valid_pts[:min(50, len(valid_pts))]

    best_score = -1
    best_config = []

    # For small n, enumerate combinations of candidates with repetition
    # For n=6, r=30, we have around 1000 combinations which is manageable
    if n <= 6:
        for combo in combinations_with_replacement(candidates, n):
            score = evaluate(combo)
            if score > best_score:
                best_score = score
                best_config = combo
    else:
        # For larger n, use only the listed candidates and iterate through combos
        if len(max_pts) >= n:
            for combo in combinations_with_replacement(max_pts, n):
                score = evaluate(combo)
                if score > best_score:
                    best_score = score
                    best_config = combo
        else:
            # Fallback: try combinations from first valid candidates
            for combo in combinations_with_replacement(valid_pts, n):
                score = evaluate(combo)
                if score > best_score:
                    best_score = score
                    best_config = combo

    # Output result
    result_lines = [str(best_score)]
    for p in best_config:
        result_lines.append(f"{p[0]} {p[1]}")
    return '\n'.join(result_lines)

